  '01_brand_overview.md': 'vector',
  '04_retreat_concept.md': 'vector',
  '12_program_overview.md': 'vector',
  '13_daily_schedule.md': 'vector',
  '14_practices_methods.md': 'vector',
  '17_community.md': 'vector',
  '19_post_retreat_integration.md': 'vector',
  '21_guardrails.md': 'internal',
  '02_tone_of_voice.md': 'internal',
  '03_target_audience.md': 'internal',
};

const points = $input.first().json?.result?.points ?? [];

// Группируем IDs по search_type
const groups = {};
for (const point of points) {
  const source = point.payload?.metadata?.source ?? '';
  const type = mapping[source] ?? 'vector';
  if (!groups[type]) groups[type] = [];
  groups[type].push(point.id);
}

// Возвращаем один item на каждый тип
return Object.entries(groups).map(([search_type, ids]) => ({
  json: { search_type, ids }
}));
